// 简化版单线程 Reactor 模型
#include <sys/epoll.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_EVENTS 1024

// 事件处理器
void handle_event(int fd, int events) {
    if (events & EPOLLIN) {
        char buf[1024];
        int n = read(fd, buf, sizeof(buf));
        if (n <= 0) {
            close(fd);
            return;
        }
        // 业务处理
        // ...
        // 写回响应
        write(fd, buf, n);
    }
}

int main() {
    int epfd = epoll_create1(0);
    struct epoll_event ev, events[MAX_EVENTS];

    // 注册 listenfd
    ev.events = EPOLLIN;
    ev.data.fd = listenfd;
    epoll_ctl(epfd, EPOLL_CTL_ADD, listenfd, &ev);

    // Reactor 事件循环
    while (1) {
        int nfds = epoll_wait(epfd, events, MAX_EVENTS, -1);
        for (int i = 0; i < nfds; i++) {
            int fd = events[i].data.fd;
            if (fd == listenfd) {
                // Accept 新连接
                int client = accept(listenfd, NULL, NULL);
                ev.events = EPOLLIN;
                ev.data.fd = client;
                epoll_ctl(epfd, EPOLL_CTL_ADD, client, &ev);
            } else {
                // 处理 IO 事件
                handle_event(fd, events[i].events);
            }
        }
    }
    return 0;
}
